script:
hits = repo.search("OldClient", glob = "src/**")
paths = {}
for h in hits:
    paths[h.path] = True
for p in sorted(paths.keys()):
    repo.edit(p, "OldClient", "NewClient", all = True)
after = repo.search("OldClient", glob = "src/**")
docs = repo.search("OldClient", glob = "docs/**")
commit()
return {
  "remaining_in_src": len(after),
  "docs_unchanged_hits": len(docs),
  "diff": repo.diff(),
}
